CREATE VIEW run_errors AS
 SELECT url_frontier.run_id,
    'url'::text AS plane,
    (url_frontier.frontier_id)::text AS ref,
    COALESCE(url_frontier.error_code, url_frontier.denial_reason) AS code,
    url_frontier.canonical_url AS subject,
    url_frontier.finished_at AS occurred_at
   FROM url_frontier
  WHERE (url_frontier.status = ANY (ARRAY['failed'::text, 'abandoned'::text, 'unreachable'::text, 'policy_blocked'::text, 'robots_blocked'::text]))
UNION ALL
 SELECT actions.run_id,
    'interaction'::text AS plane,
    (actions.action_id)::text AS ref,
    COALESCE((actions.outcome ->> 'code'::text), (actions.status)::text) AS code,
    (actions.action_kind)::text AS subject,
    actions.finished_at AS occurred_at
   FROM actions
  WHERE ((actions.status = ANY (ARRAY['failed'::action_status, 'unknown'::action_status])) OR (actions.hold = 'denied'::text));

