    late boolean DEFAULT false CONSTRAINT traffic_events_late_not_null NOT NULL,
    attribution_confidence text DEFAULT 'high'::text CONSTRAINT traffic_events_attribution_confidence_not_null NOT NULL,
    method text,
    url_redacted text,
    url_hash bytea CONSTRAINT traffic_events_url_hash_not_null NOT NULL,
    status integer,
    request_headers jsonb,
    response_headers jsonb,
    secret_value_hashes bytea[],
    body_artifact_id uuid,
    request_body_artifact_id uuid,
    finished_at timestamp with time zone,
    CONSTRAINT traffic_events_origin_check CHECK ((origin = ANY (ARRAY['page'::text, 'service_worker'::text, 'websocket'::text, 'event_source'::text, 'fetch_plane'::text])))
);

ALTER TABLE traffic_events ALTER COLUMN event_id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME traffic_events_event_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE transitions (
    transition_id uuid NOT NULL,
    run_id uuid NOT NULL,
    session_id uuid NOT NULL,
    before_state_id uuid NOT NULL,
    action_id uuid NOT NULL,
    network_epoch_id uuid,
    after_state_id uuid,
    lane trust_lane NOT NULL,
    settle_report jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE VIEW trusted_reachable_states AS
 WITH RECURSIVE reach AS (
         SELECT s.run_id,
            s.state_id
           FROM states s
          WHERE (NOT (EXISTS ( SELECT 1
                   FROM transitions t
                  WHERE (t.after_state_id = s.state_id))))
        UNION
         SELECT t.run_id,
            t.after_state_id
           FROM ((transitions t
             JOIN actions a ON ((a.action_id = t.action_id)))
             JOIN reach r ON ((r.state_id = t.before_state_id)))
          WHERE ((a.lane = 'trusted_ui'::trust_lane) AND (t.after_state_id IS NOT NULL))
        )
 SELECT run_id,
    state_id
   FROM reach;

