CREATE INDEX artifacts_sweep ON artifacts USING btree (expires_at) WHERE ((deleted_at IS NULL) AND (expires_at IS NOT NULL));

CREATE INDEX checkpoints_latest ON checkpoints USING btree (session_id, action_seq DESC);

